class Handler(BaseHTTPRequestHandler):
 def authorized(self):
  if hmac.compare_digest(self.headers.get('Authorization',''),auth):return True
  self.send_response(401);self.send_header('WWW-Authenticate','Basic realm="Control backend"');self.end_headers();return False
 def reply(self,data,kind='application/json'):
  body=data.encode() if isinstance(data,str) else json.dumps(data).encode();self.send_response(200);self.send_header('Content-Type',kind);self.send_header('Cache-Control','no-store');self.send_header('X-Frame-Options','DENY');self.end_headers();self.wfile.write(body)
 def logs(self):
  p=ROOT/'http-access.log'
  if not p.exists():return []
  with p.open('rb') as f:
   f.seek(0,2);end=f.tell();f.seek(max(CLEAR_OFFSET if CLEAR_OFFSET<=end else 0,end-200000));return f.read().decode('utf-8',errors='replace').splitlines()[-300:]
 def do_GET(self):
  if not self.authorized():return
  if self.path=='/http-logs':self.reply(self.logs());return
  if self.path=='/':self.reply(HTML,'text/html; charset=utf-8')
  elif self.path=='/status':self.reply({'running':pid() is not None,'autoAdmin':(ROOT/'.registro-admin').exists() and (ROOT/'.registro-admin').read_text().strip()=='enabled'})
  else:self.send_error(404)
 def do_POST(self):
  global CLEAR_OFFSET
  if not self.authorized():return
  if not hmac.compare_digest(self.headers.get('X-Control-Token',''),TOKEN):self.send_error(403);return
  with LOCK:
   n=pid()
   if self.path=='/clear-logs':
    path=ROOT/'http-access.log';CLEAR_OFFSET=path.stat().st_size if path.exists() else 0
    self.reply({'message':'Vista limpiada.'})
   elif self.path in ('/admin-on','/admin-off'):
    flag=ROOT/'.registro-admin';tmp=ROOT/'.registro-admin.tmp';tmp.write_text('enabled' if self.path=='/admin-on' else 'disabled');tmp.chmod(0o600);os.replace(tmp,flag)
    self.reply({'message':'Nuevos registros como ADMIN: '+('activado' if self.path=='/admin-on' else 'desactivado')})
   elif self.path=='/off':
    if n:os.kill(n,signal.SIGTERM)
    self.reply({'message':'Se solicitó apagar el backend.'})
   elif self.path=='/on':
    if not n:
     env=os.environ.copy();env.update(SERVER_PORT='8082',DB_USERNAME='postgres.ruvuaponemmepdwnqfce',DB_URL='jdbc:postgresql://aws-1-ca-central-1.pooler.supabase.com:5432/postgres')
     f=open(ROOT/'spring.log','a');subprocess.Popen(['mvn','-B','-DskipTests','spring-boot:run'],cwd=ROOT/'autopartes-backend',env=env,stdout=f,stderr=f,stdin=subprocess.DEVNULL,start_new_session=True)
    self.reply({'message':'Arranque solicitado. Espera unos segundos.'})
   else:self.send_error(404)
